// prompt() forwards an array of Content objects to generateContent, so media goes in `parts`.
prompt(
  [
    {
      role: 'user',
      parts: [
        // Base64 audio, inline (keep the whole request under ~20MB).
        { inlineData: { mimeType: 'audio/mp3', data: $.data.audioBase64 } },
        { text: 'Transcribe this voice note, then list any follow-up actions mentioned.' },
      ],
    },
  ],
  {
    model: 'gemini-2.5-flash',
  }
);

